// Des: Tests car pull, roll-up and retention on temp data
// Flo: save raw pages > page rows > pull > roll > purge > assert rows, history, phone, text
// I/O: temp dir > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const inde = @import("st-page-inde.zig"); const sqli = @import("st-stor-sqli.zig"); const stor = @import("st-carz-stor.zig"); const typz = @import("pa-carz-type.zig"); const pull = @import("ru-carz-pull.zig"); const roll = @import("ru-carz-roll.zig"); const purg = @import("ru-carz-purg.zig"); const file = @import("st-stor-file.zig"); const cfgz = @import("cf-conf-load.zig");
const NOWZ: i64 = 1_795_600_000_000; const DAYZ: i64 = 86_400_000;
fn scal(dbzz: *sqli.Dbzz, sqlz: [:0]const u8) !i64 { var stmt = try dbzz.prep(sqlz); defer stmt.fini(); _ = try stmt.step(); return stmt.colzIntz(0); }
const CHOT = "<title>Toyota Fortuner 2017 Số sàn Bạc 84.281 km - 134891221</title><div>520.000.000 đ</div><div>Mô tả chi tiết</div><div>Bán xe. Zalo 0966.353.678</div><div>Hãng</div><div>Toyota</div><div>Dòng xe</div><div>Fortuner</div><div>Năm sản xuất</div><div>2017</div><div>Hộp số</div><div>Số sàn</div><div>Nhiên liệu</div><div>Dầu</div><div>Tình trạng</div><div>Đã sử dụng</div><div>Bình Dương</div>";
fn addzPage(dbzz: *sqli.Dbzz, aren: std.mem.Allocator, rawd: []const u8, urlz: []const u8, html: []const u8, code: i64, fetc: i64) !void { const save = try file.fileSave(aren, std.testing.io, rawd, html); var buff: [512]u8 = undefined; const text = try std.fmt.bufPrint(&buff, "INSERT OR REPLACE INTO page(urlz,hexz,etag,lmod,code,tier,vend,fetc,next) VALUES('{s}','{s}','','',{d},1,'',{d},1);", .{ urlz, save.hexz, code, fetc }); buff[text.len] = 0; try dbzz.exec(buff[0..text.len :0]); }
test "pull parses detail pages once, skips listings, touches unchanged pages, marks 404 gone, honors dry run" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const rawd = try std.fs.path.join(aren.allocator(), &.{ dirz, "raw" }); const url1 = "https://xe.chotot.com/mua-ban-oto-binh-duong/134891221.htm"; const url2 = "https://xe.chotot.com/mua-ban-oto"; try addzPage(&dbzz, aren.allocator(), rawd, url1, CHOT, 200, NOWZ - DAYZ); try addzPage(&dbzz, aren.allocator(), rawd, url2, "<title>Mua bán ô tô</title>", 200, NOWZ - DAYZ); const conf: cfgz.Conf = .{};
    const dryz = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, NOWZ, true); try std.testing.expectEqual(@as(u32, 1), dryz.pars); try std.testing.expectEqual(@as(i64, 0), try scal(&dbzz, "SELECT count(*) FROM carz;")); const rsl1 = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, NOWZ, false); try std.testing.expectEqual(@as(u32, 1), rsl1.news); try std.testing.expectEqual(@as(u32, 1), rsl1.skip); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE make='Toyota' AND pric=520000000 AND kmzz=84281;")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE phon='0966353678' AND instr(text,'0966')=0;")); const rsl2 = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, NOWZ + DAYZ, false); try std.testing.expectEqual(@as(u32, 0), rsl2.news + rsl2.chan); try std.testing.expectEqual(@as(u32, 0), rsl2.pars);
    try addzPage(&dbzz, aren.allocator(), rawd, url1, CHOT, 200, NOWZ + DAYZ); const rsl3 = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, NOWZ + 2 * DAYZ, false); try std.testing.expectEqual(@as(u32, 0), rsl3.pars); try std.testing.expectEqual(@as(i64, NOWZ + DAYZ), try scal(&dbzz, "SELECT lasz FROM carz;")); try dbzz.exec("UPDATE page SET code=404 WHERE urlz='https://xe.chotot.com/mua-ban-oto-binh-duong/134891221.htm';"); const rsl4 = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, NOWZ + 3 * DAYZ, false); try std.testing.expectEqual(@as(u32, 1), rsl4.gone); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE stat=1 AND grsn='http';")); }
test "pull saves the seller as a contact and links the car row; cont_enab off saves none" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const rawd = try std.fs.path.join(aren.allocator(), &.{ dirz, "raw" }); const html = "<title>Porsche Panamera 2020 giá 3 tỉ 250 triệu - 1</title><div>Năm sản xuất</div><div>2020</div><div>Tin cùng người bán</div><div>AUTO CHỐT</div><div>0907 140 000</div>"; try addzPage(&dbzz, aren.allocator(), rawd, "https://oto.com.vn/mua-ban-xe-porsche-ha-noi/ho-tro-aidxc1", html, 200, NOWZ - DAYZ); var conf: cfgz.Conf = .{}; conf.cont_enab = false; _ = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, NOWZ, false); try std.testing.expectEqual(@as(i64, 0), try scal(&dbzz, "SELECT count(*) FROM cont;")); try dbzz.exec("DELETE FROM carz;"); conf.cont_enab = true; const rslt = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, NOWZ, false); try std.testing.expectEqual(@as(u32, 1), rslt.cnts); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM cont WHERE kind='dealer' AND name='AUTO CHỐT' AND phon='0907140000';")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz z JOIN cont c ON c.cidz=z.cont;")); }
test "pull: a lost raw file is counted, not fatal; a sold notice marks gone" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const rawd = try std.fs.path.join(aren.allocator(), &.{ dirz, "raw" }); try dbzz.exec("INSERT INTO page(urlz,hexz,etag,lmod,code,tier,vend,fetc,next) VALUES('https://xe.chotot.com/a-b/134891222.htm','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','','',200,1,'',1,1);"); const conf: cfgz.Conf = .{}; const rsl1 = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, NOWZ, false); try std.testing.expectEqual(@as(u32, 1), rsl1.lost); try addzPage(&dbzz, aren.allocator(), rawd, "https://xe.chotot.com/a-b/134891223.htm", "<div>Tin đã bán</div><title>Toyota Fortuner 2017 giá 500 triệu</title>", 200, NOWZ); const rsl2 = try pull.pullRunz(&dbzz, std.testing.io, dirz, conf, allo, NOWZ, false); try std.testing.expectEqual(@as(u32, 1), rsl2.news); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE stat=1 AND grsn='page';")); }
fn mkzz(urlz: []const u8, pric: i64, year: i64, kmzz: i64) typz.Carz { return .{ .urlz = urlz, .site = "x.vn", .lidz = "1", .make = "Toyota", .modl = "Fortuner", .year = year, .cond = "used", .kmzz = kmzz, .pric = pric, .prov = "HN", .gear = "AT", .powr = "GAS", .phon = "0966353678", .text = "long text", .xtra = "{\"a\":\"b\"}" }; }
test "roll-up: quartiles per group for the active rows only, week key is a Monday, rerun replaces" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var stoz = try stor.storOpen(&dbzz, NOWZ); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); const pris = [_]i64{ 400, 500, 600, 700, 800 }; for (pris, 0..) |pric, indx| { var urlb: [40]u8 = undefined; const urlz = try std.fmt.bufPrint(&urlb, "https://x.vn/a-{d}", .{indx}); _ = try stor.carzSave(&stoz, mkzz(urlz, pric * 1_000_000, 2020, @as(i64, @intCast(indx)) * 50000), "h", NOWZ - @as(i64, @intCast(indx)) * 20000); } _ = try stor.carzSave(&stoz, mkzz("https://x.vn/old", 100_000_000, 2020, 1), "h", NOWZ - 60 * DAYZ);
    try std.testing.expectEqual(@as(u32, 1), try roll.rollRunz(&dbzz, aren.allocator(), NOWZ, 14 * DAYZ, false)); try std.testing.expectEqual(@as(i64, 5), try scal(&dbzz, "SELECT cont FROM carr;")); try std.testing.expectEqual(@as(i64, 600_000_000), try scal(&dbzz, "SELECT pmed FROM carr;")); try std.testing.expectEqual(@as(i64, 500_000_000), try scal(&dbzz, "SELECT pq25 FROM carr;")); try std.testing.expectEqual(@as(i64, 700_000_000), try scal(&dbzz, "SELECT pq75 FROM carr;")); try std.testing.expectEqual(@as(i64, 100000), try scal(&dbzz, "SELECT kmed FROM carr;")); const wkzz = roll.weekOfzz(NOWZ); try std.testing.expectEqual(wkzz, try scal(&dbzz, "SELECT wkzz FROM carr;")); try std.testing.expectEqual(@as(i64, 20261123), roll.weekOfzz(1795600000000)); _ = try roll.rollRunz(&dbzz, aren.allocator(), NOWZ, 14 * DAYZ, false); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carr;")); try std.testing.expectEqual(@as(u32, 1), try roll.rollRunz(&dbzz, aren.allocator(), NOWZ, 14 * DAYZ, true)); }
test "retention: active rows untouched; phone, text, history, rows go by age; rows wait for a roll-up" { const allo = std.testing.allocator; var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var buff: [160]u8 = undefined; const dirz = try std.fmt.bufPrint(&buff, ".zig-cache/tmp/{s}", .{tmpz.sub_path}); var dbzz = try inde.pageOpen(allo, std.testing.io, dirz); defer dbzz.close(); var stoz = try stor.storOpen(&dbzz, NOWZ); const conf: cfgz.Conf = .{};
    _ = try stor.carzSave(&stoz, mkzz("https://x.vn/live", 500_000_000, 2020, 1), "h", NOWZ); const gone: [3][]const u8 = .{ "https://x.vn/g-100", "https://x.vn/g-400", "https://x.vn/g-800" }; const ages = [_]i64{ 100, 400, 800 }; for (gone, ages) |urlz, agez| { for ([_]i64{ 500, 450, 400 }, 0..) |pric, step| { _ = try stor.carzSave(&stoz, mkzz(urlz, pric * 1_000_000, 2020, 1), "h", NOWZ - agez * DAYZ + @as(i64, @intCast(step)) * DAYZ); } try stor.goneMark(&stoz, urlz, NOWZ - agez * DAYZ, "http"); }
    const dryz = try purg.purgRunz(&dbzz, conf, NOWZ, true); try std.testing.expectEqual(@as(u32, 3), dryz.pers); try std.testing.expectEqual(@as(u32, 2), dryz.text); try std.testing.expectEqual(@as(u32, 2), dryz.hist); try std.testing.expectEqual(@as(u32, 0), dryz.rows); try std.testing.expectEqual(@as(i64, 4), try scal(&dbzz, "SELECT count(*) FROM carz WHERE phon<>'';"));
    const rsl1 = try purg.purgRunz(&dbzz, conf, NOWZ, false); try std.testing.expectEqual(@as(u32, 3), rsl1.pers); try std.testing.expectEqual(@as(u32, 2), rsl1.text); try std.testing.expectEqual(@as(u32, 2), rsl1.hist); try std.testing.expectEqual(@as(u32, 0), rsl1.rows); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE phon<>'' AND stat=0;")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM carz WHERE text<>'';")); try std.testing.expectEqual(@as(i64, 4), try scal(&dbzz, "SELECT count(*) FROM carz;")); try std.testing.expectEqual(@as(i64, 2), try scal(&dbzz, "SELECT count(*) FROM carp WHERE urlz='https://x.vn/g-400';")); try std.testing.expectEqual(@as(i64, 3), try scal(&dbzz, "SELECT count(*) FROM carp WHERE urlz='https://x.vn/g-100';")); try std.testing.expectEqual(@as(i64, 16), try scal(&dbzz, "SELECT length(phsh) FROM carz WHERE urlz='https://x.vn/g-800';"));
    var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); _ = try roll.rollRunz(&dbzz, aren.allocator(), NOWZ, 14 * DAYZ, false); const rsl2 = try purg.purgRunz(&dbzz, conf, NOWZ, false); try std.testing.expectEqual(@as(u32, 1), rsl2.rows); try std.testing.expectEqual(@as(i64, 3), try scal(&dbzz, "SELECT count(*) FROM carz;")); try std.testing.expectEqual(@as(i64, 0), try scal(&dbzz, "SELECT count(*) FROM carp WHERE urlz='https://x.vn/g-800';")); try std.testing.expectEqual(@as(i64, 1), try scal(&dbzz, "SELECT count(*) FROM carz WHERE stat=0;")); }
